// Real filesystem/SQLite adapter cutpoints in a disposable child only.
import Database from 'better-sqlite3';
import {mkdir,writeFile} from 'node:fs/promises';
import path from 'node:path';
import {randomUUID,createHash} from 'node:crypto';
import fs from 'node:fs';
import fsPromises from 'node:fs/promises';
import {syncBuiltinESMExports} from 'node:module';
import {createBackupManager} from '../../packages/backend/platform/backup/public';
import {createManagedCopies} from '../../packages/backend/platform/backup/managed-copies';
const root=process.argv[2]!,cut=process.argv[3]!,active=path.join(root,'workspace');await mkdir(path.join(active,'blobs'),{recursive:true});const db=new Database(path.join(active,'career.sqlite'));db.exec('CREATE TABLE platform_blobs(id TEXT,digest TEXT,size INTEGER,state TEXT);CREATE TABLE platform_artifact_retention(blob_id TEXT);CREATE TABLE fact(body TEXT);');db.prepare('INSERT INTO fact VALUES (?)').run('committed career data');const id=randomUUID(),bytes=Buffer.from('retained blob');await writeFile(path.join(active,'blobs',id),bytes);db.prepare('INSERT INTO platform_blobs VALUES (?,?,?,?)').run(id,createHash('sha256').update(bytes).digest('hex'),bytes.length,'published');db.prepare('INSERT INTO platform_artifact_retention VALUES (?)').run(id);let armed=false;
function pause(stage:string){if(!armed||cut!==stage)return;process.send?.({stage});Atomics.wait(new Int32Array(new SharedArrayBuffer(4)),0,0);}
const registry=createManagedCopies(root),manager=createBackupManager({root,registry,getActiveRoot:()=>active,maintenance:async work=>work(),sanitizeCandidate:()=>{},validateRelations:()=>{},async prepareCandidate(filename,destination){pause('db-snapshot');const candidate=new Database(filename);try{pause('blob-enumeration');const artifacts=candidate.prepare("SELECT DISTINCT b.id,b.digest,b.size FROM platform_blobs b JOIN platform_artifact_retention r ON r.blob_id=b.id WHERE b.state='published'").all() as {id:string;digest:string;size:number}[];pause('filtered-publish');candidate.prepare('VACUUM INTO ?').run(destination);return {schemaVersion:0,artifacts};}finally{candidate.close();}},async inspectCandidate(filename){pause('hash-verification');const candidate=new Database(filename,{readonly:true});try{return {schemaVersion:0,artifacts:candidate.prepare("SELECT DISTINCT b.id,b.digest,b.size FROM platform_blobs b JOIN platform_artifact_retention r ON r.blob_id=b.id WHERE b.state='published'").all() as {id:string;digest:string;size:number}[]};}finally{candidate.close();}}});
await manager.backup(1);
const realOpen=fsPromises.open.bind(fsPromises);fsPromises.open=(async(...args:Parameters<typeof fsPromises.open>)=>{if(String(args[0]).includes('/backups/')&&String(args[0]).includes('/blobs/')&&args[1]==='wx')pause('blob-copy');return realOpen(...args);}) as typeof fsPromises.open;
const fdPaths=new Map<number,string>(),realOpenSync=fs.openSync.bind(fs),realWriteSync=fs.writeFileSync.bind(fs);fs.openSync=((...args:Parameters<typeof fs.openSync>)=>{const fd=realOpenSync(...args);fdPaths.set(fd,String(args[0]));return fd;}) as typeof fs.openSync;fs.writeFileSync=((...args:Parameters<typeof fs.writeFileSync>)=>{if(typeof args[0]==='number'&&fdPaths.get(args[0])?.includes('/backup.json.'))pause('manifest');return realWriteSync(...args);}) as typeof fs.writeFileSync;syncBuiltinESMExports();
const update=registry.update.bind(registry);registry.update=(id,patch)=>{if(patch.state==='ready')pause('atomic-publish');return update(id,patch);};armed=true;await manager.backup(1);throw Error('cut_not_reached');
